import sys
from collections import deque

class RBNode:
    def __init__(self, key, color='R', left=None, right=None, parent=None):
        self.key = key
        self.color = color
        self.left = left
        self.right = right
        self.parent = parent

class RedBlackTree:
    def __init__(self):
        self.NIL = RBNode(None, 'B')
        self.NIL.left = self.NIL
        self.NIL.right = self.NIL
        self.NIL.parent = self.NIL
        self.root = self.NIL

    def left_rotate(self, x):
        y = x.right
        x.right = y.left
        if y.left != self.NIL:
            y.left.parent = x
        y.parent = x.parent
        if x.parent == self.NIL:
            self.root = y
        elif x == x.parent.left:
            x.parent.left = y
        else:
            x.parent.right = y
        y.left = x
        x.parent = y

    def right_rotate(self, y):
        x = y.left
        y.left = x.right
        if x.right != self.NIL:
            x.right.parent = y
        x.parent = y.parent
        if y.parent == self.NIL:
            self.root = x
        elif y == y.parent.right:
            y.parent.right = x
        else:
            y.parent.left = x
        x.right = y
        y.parent = x

    def insert(self, key, color):
        node = RBNode(key, color)
        node.left = self.NIL
        node.right = self.NIL
        node.parent = self.NIL

        current = self.root
        parent = self.NIL

        while current != self.NIL:
            parent = current
            if node.key < current.key:
                current = current.left
            else:
                current = current.right

        node.parent = parent
        if parent == self.NIL:
            self.root = node
        elif node.key < parent.key:
            parent.left = node
        else:
            parent.right = node

        return node

    def minimum(self, node):
        while node.left != self.NIL:
            node = node.left
        return node

    def transplant(self, u, v):
        if u.parent == self.NIL:
            self.root = v
        elif u == u.parent.left:
            u.parent.left = v
        else:
            u.parent.right = v
        v.parent = u.parent

    def delete_node(self, key):
        z = self.root
        while z != self.NIL and z.key != key:
            if key < z.key:
                z = z.left
            else:
                z = z.right

        if z == self.NIL:
            return

        y = z
        y_original_color = y.color

        if z.left == self.NIL:
            self.transplant(z, z.right)
        elif z.right == self.NIL:
            self.transplant(z, z.left)
        else:
            y = self.minimum(z.right)
            y_original_color = y.color
            if y.parent == z:
                y.parent = y
            else:
                self.transplant(y, y.right)
                y.right = z.right
                y.right.parent = y
            self.transplant(z, y)
            y.left = z.left
            y.left.parent = y
            y.color = z.color

        if y_original_color == 'B':
            self.delete_fixup(y)

    def delete_fixup(self, x):
        while x != self.root and x.color == 'B':
            if x == x.parent.left:
                w = x.parent.right
                if w.color == 'R':
                    w.color = 'B'
                    x.parent.color = 'R'
                    self.left_rotate(x.parent)
                    w = x.parent.right
                if w.left.color == 'B' and w.right.color == 'B':
                    w.color = 'R'
                    x = x.parent
                else:
                    if w.right.color == 'B':
                        w.left.color = 'B'
                        w.color = 'R'
                        self.right_rotate(w)
                        w = x.parent.right
                    w.color = x.parent.color
                    x.parent.color = 'B'
                    w.right.color = 'B'
                    self.left_rotate(x.parent)
                    x = self.root
            else:
                w = x.parent.left
                if w.color == 'R':
                    w.color = 'B'
                    x.parent.color = 'R'
                    self.right_rotate(x.parent)
                    w = x.parent.left
                if w.right.color == 'B' and w.left.color == 'B':
                    w.color = 'R'
                    x = x.parent
                else:
                    if w.left.color == 'B':
                        w.right.color = 'B'
                        w.color = 'R'
                        self.left_rotate(w)
                        w = x.parent.left
                    w.color = x.parent.color
                    x.parent.color = 'B'
                    w.left.color = 'B'
                    self.right_rotate(x.parent)
                    x = self.root
        x.color = 'B'

    def level_order(self):
        result_keys = []
        result_colors = []

        if self.root == self.NIL:
            return result_keys, result_colors

        queue = deque([self.root])

        while queue:
            node = queue.popleft()

            if node != self.NIL:
                result_keys.append(node.key)
                result_colors.append(node.color)
                queue.append(node.left)
                queue.append(node.right)

        return result_keys, result_colors


def build_tree_from_level_order(keys, colors):
    if not keys:
        return RedBlackTree()

    tree = RedBlackTree()
    nodes = []

    for i in range(len(keys)):
        color = 'B' if i == 0 else colors[i]
        node = RBNode(keys[i], color)
        node.left = tree.NIL
        node.right = tree.NIL
        node.parent = tree.NIL
        nodes.append(node)

    for i in range(len(keys)):
        left_idx = 2 * i + 1
        right_idx = 2 * i + 2

        if left_idx < len(keys):
            nodes[i].left = nodes[left_idx]
            nodes[left_idx].parent = nodes[i]

        if right_idx < len(keys):
            nodes[i].right = nodes[right_idx]
            nodes[right_idx].parent = nodes[i]

    tree.root = nodes[0] if nodes else tree.NIL
    return tree


